/// <summary>
/// Finds a specific <c>METPickDirectorDataEntitityStaging</c> record with given parameters.
/// </summary>
/// <param name = "_salesId">Sales order.</param>
/// <param name = "_lineNum">Line number.</param>
/// <param name = "_dmfDefinitionGroup">Definition group.</param>
/// <param name = "_executionId"Execution Id.</param>
/// <param name = "_forUpdate">Determines whether the record is selected for update.</param>
/// <param name = "_concurrencyModel">Determines the concurreny model when selecting <c>METPickDirectorDataEntitityStaging</c> record.</param>
/// <returns>The record that is searched for METPickDirectorDataEntitityStaging if found.</returns>
static METPickDirectorDataEntitityStaging find(SalesId                 _salesId,
                                            LineNum                    _lineNum,
                                            DMFDefinitionGroupName     _dmfDefinitionGroup = '',
                                            DMFExecutionId             _executionId = '',
                                            boolean                    _forUpdate = false,
                                            ConcurrencyModel           _concurrencyModel = ConcurrencyModel::Auto)
{
    METPickDirectorDataEntitityStaging  pickDirectorData;

    if (_salesId)
    {
        if (_forUpdate)
        {
            pickDirectorData.selectForUpdate (_forUpdate);

            if (_concurrencyModel != ConcurrencyModel::Auto)
            {
                pickDirectorData.concurrencyModel(_concurrencyModel);
            }
        }

        select firstonly pickDirectorData
            where pickDirectorData.SalesId == _salesId
                && pickDirectorData.LineNum == _lineNum
                && pickDirectorData.DefinitionGroup == _dmfDefinitionGroup
                && pickDirectorData.ExecutionId == _executionId;
    }

    return pickDirectorData;
}

/// <summary>
/// Checks if a specific <c>METPickDirectorDataEntitityStaging</c> record exists.
/// </summary>
/// <param name = "_salesId">Sales order.</param>
/// <param name = "_lineNum">Line number.</param>
/// <param name = "_dmfDefinitionGroup">Definition group.</param>
/// <param name = "_executionId">Execution Id.</param>
/// <returns>True if the record exists; otherwise, false</returns>
static boolean exist(SalesId                   _salesId,
                    LineNum                    _lineNum,
                    DMFDefinitionGroupName     _dmfDefinitionGroup = '',
                    DMFExecutionId             _executionId = '')
{
    if (!_salesId)
    {
        return false;
    }

    return (select firstonly RecId from METPickDirectorDataEntitityStaging
                where METPickDirectorDataEntitityStaging.SalesId == _salesId
                    && METPickDirectorDataEntitityStaging.LineNum == _lineNum
                    && METPickDirectorDataEntitityStaging.DefinitionGroup == _dmfDefinitionGroup
                    && METPickDirectorDataEntitityStaging.ExecutionId == _executionId).RecId != 0;
}
